#pragma once
#include "assets.hpp"
#include "Game/System/BinaryDataChunkHolder.hpp"
// Portable, bounded adaptation of original chunk file layout (Wii big-endian).
inline void chunkWord(std::vector<uint8_t>& bytes,uint32_t word){for(int shift:{24,16,8,0})bytes.push_back(uint8_t(word>>shift));}
inline std::vector<uint8_t> encodeSaveChunks(const std::vector<const BinaryDataChunkBase*>& chunks){assetCheck(chunks.size()<=255,"Too many save chunks");std::vector<uint8_t> bytes{1,uint8_t(chunks.size()),0,0};for(auto chunk:chunks){assetCheck(chunk!=nullptr,"Null save chunk");std::vector<uint8_t> payload(4096);auto size=chunk->serialize(payload.data(),uint32_t(payload.size()));assetCheck(size>=0&&size<=int(payload.size()),"Invalid save payload size");chunkWord(bytes,chunk->getSignature());chunkWord(bytes,chunk->makeHeaderHashCode());chunkWord(bytes,uint32_t(size)+12);bytes.insert(bytes.end(),payload.begin(),payload.begin()+size);}return bytes;}
inline bool decodeSaveChunks(const std::vector<uint8_t>& bytes,const std::vector<BinaryDataChunkBase*>& chunks){if(bytes.size()<4||bytes[0]!=1)return false;struct Entry{BinaryDataChunkBase* chunk;size_t offset,size;};std::vector<Entry> entries;size_t offset=4;for(unsigned i=0;i<bytes[1];++i){if(offset>bytes.size()||bytes.size()-offset<12)return false;auto signature=be32(bytes.data()+offset),hash=be32(bytes.data()+offset+4),size=be32(bytes.data()+offset+8);if(size<12||size>bytes.size()-offset)return false;BinaryDataChunkBase* target=nullptr;for(auto chunk:chunks){if(!chunk)return false;if(chunk->getSignature()==signature){target=chunk;break;}}if(target){if(hash!=target->makeHeaderHashCode())return false;for(const auto& entry:entries)if(entry.chunk==target)return false;entries.push_back({target,offset+12,size-12});}offset+=size;}for(const auto& entry:entries){int result=entry.chunk->deserialize(bytes.data()+entry.offset,uint32_t(entry.size));if(result!=0&&result!=1)return false;}return true;}

